import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # ---------- cheap counts ----------
    op_c = 0
    op_d = 0
    for a in op:
        if a == 'C':
            op_c += 1
        else:
            op_d += 1
    my_c = 0
    my_d = 0
    for a in me:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    last_me = me[-1]
    last_op = op[-1]

    # ---------- ENDGAME ----------
    # Known pure/tolerant cooperators: exploit hard in the tail.
    if n >= 88 and op_d <= 2:
        return 'D'
    if n >= 96:
        if op_d <= 6:
            return 'D'
        # Against heavy defectors, also defect (DD=1 beats CD=0).
        if op_d * 2 >= n:
            return 'D'

    # ---------- SUSTAINED DEFECTOR DETECTION ----------
    # If opponent is essentially a pure defector, stop feeding them C's.
    if n >= 4 and op_c == 0:
        return 'D'

    # ---------- RESPOND TO LAST ACTION ----------
    if last_op == 'D':
        # Opponent defected last.
        # If they've defected a lot relative to cooperations, punish.
        if op_d * 3 > n and op_d >= 2:
            # occasional probe to break DD lock against TFT-like botched openings
            if last_me == 'D' and rng.random() < 0.12:
                return 'C'
            return 'D'
        # Mild defector: retaliate but forgive quickly to restore cooperation.
        if last_me == 'D':
            # We were already punishing; try to restart (four_D_TFT recovery).
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        # We cooperated and got defected into: retaliate, but not too long.
        if rng.random() < 0.80:
            return 'D'
        return 'C'

    # last_op == 'C' -- opponent cooperated last.
    # If we're in a bad mutual-defection rhythm and opponent just opened up, take it.
    if last_me == 'D':
        return 'C'

    # ---------- PUNISH PROLONGED DEFECTION ----------
    if n >= 6:
        # Count opponent defections in recent window to react to bursts.
        window = 8
        start = n - window
        if start < 0:
            start = 0
        recent_op_d = 0
        recent_op_n = 0
        for i in range(start, n):
            recent_op_n += 1
            if op[i] == 'D':
                recent_op_d += 1
        if recent_op_n >= 4 and recent_op_d * 2 > recent_op_n:
            return 'D'
        if recent_op_n >= 4 and recent_op_d == 0:
            # All good: cooperate, but exploit pure cooperators late.
            if n >= 80 and op_d * 10 <= n:
                return 'D' if rng.random() < 0.55 else 'C'
            return 'C'

    # ---------- EARLY / DEFAULT: build trust then subtle exploitation ----------
    if op_d == 0:
        # Pure cooperator so far.
        if n >= 25:
            # Opportunistic exploitation: alternate to keep them cooperating.
            return 'D' if (n % 3 == 0) else 'C'
        return 'C'

    # Mostly cooperative opponent: lock in cooperation.
    if op_d * 4 <= n:
        if n >= 80:
            return 'D' if rng.random() < 0.45 else 'C'
        return 'C'

    # Mostly defective opponent: protect ourselves.
    if op_d * 2 > n:
        if last_me == 'D':
            if rng.random() < 0.10:
                return 'C'
            return 'D'
        if last_op == 'C' and rng.random() < 0.7:
            return 'C'
        return 'D'

    # Middle ground: tit-for-tat-ish, favor cooperation with light probing.
    if n < 80 and rng.random() < 0.03:
        return 'D'
    return 'C'
